package com.onlinelibrary.controller;
import com.onlinelibrary.dao.impl.NotificationPreferenceDAOImpl; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/member/preferences") public class NotificationPreferenceServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{r.setAttribute("preferences",new NotificationPreferenceDAOImpl().find(WebSupport.uid(r)));WebSupport.view(r,s,"notification-preferences.jsp");}catch(Exception e){WebSupport.fail(r,s,e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{new NotificationPreferenceDAOImpl().save(WebSupport.uid(r),r.getParameter("due")!=null,r.getParameter("overdue")!=null,r.getParameter("arrivals")!=null);s.sendRedirect(r.getContextPath()+"/member/preferences?message=Preferences+saved");}catch(Exception e){s.sendError(500,e.getMessage());}}}
